      ro: ["Captură anuală: 5.000 de tone.", "Principalele specii: ton (40%), macrou (30%), creveți (10%).", "Numărul ambarcațiunilor: 100, majoritatea canoe.", "Capacitate de procesare: 500 de tone/an.", "Contribuție economică: 2 milioane de dolari anual.", "Proiecte de acvacultură: 10 iazuri (2 ha)."],
      en: ["Annual catch: approximately 5,000 tons.", "Main species: tuna (40%), mackerel (30%), shrimp (10%).", "Number of fishing vessels: about 100, mostly canoes.", "Processing capacity: 500 tons per year.", "Local economic contribution: $2 million annually.", "Aquaculture projects: 10 ponds covering 2 hectares (2023)."],
      es: ["Captura anual de pescado: aprox. 5.000 toneladas.", "Principales especies: atún (40%), caballa (30%), camarones (10%).", "Número de barcos pesqueros: unos 100 (principalmente canoas y lanchas a motor).", "Capacidad de procesamiento: 500 toneladas al año.", "Contribución a la economía local: 2 millones de dólares de facturación anual.", "Proyectos de acuicultura: 10 estanques con una superficie de 2 hectáreas (2023)."],
      pt: ["Captura anual de peixe: aprox. 5.000 toneladas.", "Principais espécies: atum (40%), cavala (30%), camarão (10%).", "Número de barcos de pesca: cerca de 100 (principalmente canoas e pequenos barcos a motor).", "Capacidade de processamento: 500 toneladas por ano.", "Contribuição para a economia local: 2 milhões de dólares de volume de negócios anual.", "Projectos de aquicultura: 10 tanques com uma área de 2 hectares (2023)."],
      fr: ["Capture annuelle de poisson : environ 5 000 tonnes.", "Principales espèces : thon (40 %), maquereau (30 %), crevettes (10 %).", "Nombre de bateaux de pêche : environ 100 (principalement des pirogues et petits bateaux à moteur).", "Capacité de transformation : 500 tonnes par an.", "Contribution à l'économie locale : 2 millions de dollars de chiffre d'affaires annuel.", "Projets d'aquaculture : 10 étangs sur une surface de 2 hectares (2023)."],
